      best: ['in-place group reversal: O(1) extra space', "function reverseKGroup(head, k) {\n  const dummy = new ListNode(0, head);\n  let groupPrev = dummy;\n  while (true) {\n    let kth = groupPrev;\n    for (let i = 0; i < k && kth; i++) kth = kth.next;\n    if (!kth) break;                                  // fewer than k left\n    const groupNext = kth.next;\n    let prev = groupNext, curr = groupPrev.next;\n    while (curr !== groupNext) { const nx = curr.next; curr.next = prev; prev = curr; curr = nx; }\n    const oldFirst = groupPrev.next;\n    groupPrev.next = kth;                             // kth is the new group head\n    groupPrev = oldFirst;                             // old first is now the tail\n  }\n  return dummy.next;\n}\nconsole.log(toArray(reverseKGroup(fromArray([1, 2, 3, 4, 5]), 2)));", '[ 2, 1, 4, 3, 5 ]'],
