      ex: { prompt: 'Write reverseKGroup(values, k): build the list, reverse every consecutive group of k nodes in place (leave a final shorter group as is), and return toArray(head).', py: "def reverseKGroup(values, k):\n    dummy = ListNode(0, fromArray(values))\n    group_prev = dummy\n    while True:\n        kth = group_prev\n        for _ in range(k):\n            kth = kth.next if kth else None\n        if not kth:\n            break\n        group_next = kth.next\n        prev, cur = group_next, group_prev.next\n        while cur is not group_next:\n            cur.next, prev, cur = prev, cur, cur.next\n        first = group_prev.next\n        group_prev.next = kth\n        group_prev = first\n    return toArray(dummy.next)\n", sig: "(int[] values, int k) -> int[]", java: "class Solution {\n    public int[] reverseKGroup(int[] values, int k) {\n        ListNode dummy = new ListNode(0, fromArray(values)), groupPrev = dummy;\n        while (true) {\n            ListNode kth = groupPrev;\n            for (int i = 0; i < k && kth != null; i++) kth = kth.next;\n            if (kth == null) break;\n            ListNode groupNext = kth.next, prev = groupNext, cur = groupPrev.next;\n            while (cur != groupNext) {\n                ListNode next = cur.next;\n                cur.next = prev;\n                prev = cur;\n                cur = next;\n            }\n            ListNode first = groupPrev.next;\n            groupPrev.next = kth;\n            groupPrev = first;\n        }\n        return toArray(dummy.next);\n    }\n}\n", cpp: "class Solution {\npublic:\n    vector<int> reverseKGroup(vector<int>& values, int k) {\n        ListNode dummy(0, fromArray(values));\n        ListNode* groupPrev = &dummy;\n        while (true) {\n            ListNode* kth = groupPrev;\n            for (int i = 0; i < k && kth; i++) kth = kth->next;\n            if (!kth) break;\n            ListNode* groupNext = kth->next;\n            ListNode* prev = groupNext;\n            ListNode* cur = groupPrev->next;\n            while (cur != groupNext) {\n                ListNode* next = cur->next;\n                cur->next = prev;\n                prev = cur;\n                cur = next;\n            }\n            ListNode* first = groupPrev->next;\n            groupPrev->next = kth;\n            groupPrev = first;\n        }\n        return toArray(dummy.next);\n    }\n};\n", fn: 'reverseKGroup', params: 'values, k', helpers: LIST, cases: [{ args: [[1, 2, 3, 4, 5], 2], expect: [2, 1, 4, 3, 5] }, { args: [[1, 2, 3, 4, 5], 3], expect: [3, 2, 1, 4, 5] }, { args: [[1], 1], expect: [1] }, { args: [[1, 2, 3, 4], 4], expect: [4, 3, 2, 1] }], solution: 'function reverseKGroup(values,k){const d=new ListNode(0,fromArray(values));let gp=d;while(true){let kth=gp;for(let i=0;i<k&&kth;i++)kth=kth.next;if(!kth)break;const gn=kth.next;let prev=gn,cur=gp.next;while(cur!==gn){const nx=cur.next;cur.next=prev;prev=cur;cur=nx}const f=gp.next;gp.next=kth;gp=f}return toArray(d.next)}', hint: 'For each full group: find the k-th node, reverse up to it, and reconnect.' },
